export class ValidationService{static cleanDigits(t){return t?String(t).replace(/\D/g,""):""}static isTestMode(t){if(!t)return!1;return String(t).trim().startsWith("..")}static normalizePhone(t){if(!t)return"";let e=String(t).trim();e.startsWith("..")&&(e=e.slice(2));let r=e.replace(/\D/g,"");return r.length>10&&r.startsWith("977")&&(r=r.slice(3)),r}static isValidPhone(t){return!(!t||"string"!=typeof t)&&/^[0-9]{10}$/.test(t)}static isTestOtpCode(t){if(!t)return!1;const e=String(t).trim();return/^0{4,6}$/.test(e)}static sanitize(t){return t&&"string"==typeof t?t.replace(/[<>'"&]/g,t=>{switch(t){case"<":return"&lt;";case">":return"&gt;";case"'":return"&#39;";case'"':return"&quot;";case"&":return"&amp;";default:return t}}).trim():""}}"undefined"!=typeof window&&(window.ValidationService=ValidationService);